import asyncio

async def run_all(async_tools):
    # overlap I/O waits; total time ~= slowest single call
    return await asyncio.gather(*[t() for t in async_tools])

# blocking tools instead? use a thread pool:
from concurrent.futures import ThreadPoolExecutor
def run_blocking(fns):
    with ThreadPoolExecutor(max_workers=8) as ex:
        return list(ex.map(lambda f: f(), fns))

