from concurrent.futures import ThreadPoolExecutor

def get_price(item):
    return {"widget": 4.0, "gadget": 6.0}[item]   # KeyError on unknown

def get_stock(item):
    return 42

TOOLS = {"get_price": get_price, "get_stock": get_stock}

tool_calls = [
    {"id": "1", "name": "get_price", "args": {"item": "widget"}},
    {"id": "2", "name": "get_price", "args": {"item": "unknown"}},  # will fail
    {"id": "3", "name": "get_stock", "args": {"item": "widget"}},
]

def run_one(call):
    try:
        result = TOOLS[call["name"]](**call["args"])
        return call["id"], str(result)
    except Exception as e:
        return call["id"], f"error: {type(e).__name__}"   # isolate failure

with ThreadPoolExecutor(max_workers=4) as ex:
    results = dict(ex.map(run_one, tool_calls))

for call in tool_calls:
    print(call["id"], "->", results[call["id"]])
